// Generated by scripts/prepare-handout.py; student materials only.
(() => {
  const files = {"lecture_note_04.md": "", "lesson04.py": "", "lesson04.R": "", "exercise04.py": "", "exercise04.R": "", "lesson04-student.zip": ""};
  const urls = new Map(Object.entries(files).map(([name, encoded]) => {
    const bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
    return [name, URL.createObjectURL(new Blob([bytes], {type: 'application/octet-stream'}))];
  }));
  function prepare(link) {
    const url = urls.get(link?.getAttribute('download'));
    if (url) link.href = url;
  }
  document.querySelectorAll('a[download]').forEach(prepare);
  document.addEventListener('click', event => prepare(event.target.closest?.('a[download]')));
})();
